insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4051e636-695d-4534-936e-1f530668bf29', 'ja', '質問が続きすぎると、なぜ会話が偏るのですか？', '["彼女に、ほとんどの負担を負わせるから", "分かち合うのではなく、情報をもらうばかりに感じられるから", "注意を払っていることを示すから"]'::jsonb, '立て続けの質問は、一方が与え、もう一方が受け取るだけの偏りを生みます。')
