insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cd2af01-a10e-4c9e-b164-6c82a959ca1f', 'ja', '自分の正しさを証明しようと押すことは、なぜつながりを弱めるのですか？', '["会話を勝負に変えるから", "つながりよりも、正しくあることを優先していると伝えるから", "周りがよく見えていることを示すから", "彼女に、「違う」ではなく「間違っている」と感じさせるから"]'::jsonb, '緊張を生むのは、意見の違いそのものではなく、自分の正しさを証明したいという気持ちです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4d5ba9c1-712a-4d9d-b8a1-4ffec08ad96c', 'ja', '理解するために聞くことを可能にする、考え方の切り替えは何ですか？', '["気の利いた返事を、前もって準備すること", "先を考えずに、その場にしっかりいること", "自分のエピソードが、彼女のものとどう重なるかに注目すること", "エネルギーを保つために、すばやく反応すること"]'::jsonb, 'その場にいるには、前もって考えた返事を手放す必要があります。')
