insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59ddb591-0f25-456d-abef-ddcf1bc55c9f', 'ja', '彼女が、旅先での笑える失敗談を話します。お返しのエピソードとして、何ができますか？', '["似たような笑える小話で合わせる", "自分の旅行歴をすべて話す", "まったく別の話題に飛ぶ", "エピソードを話す代わりに、アドバイスをする"]'::jsonb, '簡潔に、構成を整えて話し、彼女のエネルギーに合わせて、打ち解けていきましょう。')
