insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('65941383-8920-456d-9564-8f938de86fed', 'ja', '意見が違っても、つながりを切らないために役立つ行動は、どれですか？', '["自分の見方を、絶対の真実として示すこと", "彼女の考えの筋道について尋ねること", "落ち着いたトーンを保つこと", "両方の見方が、並んで存在することを認めること"]'::jsonb, '違いを否定するのではなく、掘り下げるとき、つながりは保たれます。')
