insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66cbe1b3-1585-4d3f-b00f-bb1fcf3143d3', 'ja', '彼女の話を受け止めずに先へ進むと、何が起こりますか？', '["急いでいるように聞こえる", "彼女の伝えたことを、理解していないかもしれないと伝わる", "会話の話題が減る", "流れが遅くなる"]'::jsonb, '受け止めることは、理解を示します。次の質問をする前に、ひと言添えましょう。')
