insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('68abae72-376e-4c38-bd5f-a63ad5d4ed56', 'ja', '彼女が、きつい仕事の締め切りに間に合わせたばかりだという短いエピソードを話します。どう返しますか？', '["受け止めてから、自分が乗り越えた似たような仕事の苦労を話す", "すぐにキャリアのアドバイスをする", "自分の週末の予定の話に切り替える"]'::jsonb, '簡潔で、関係のあるエピソードで彼女のエネルギーに合わせ、打ち解けていきましょう。')
