  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75148042-557e-4fcd-b9cf-a733e31a8702', 'ja', '彼女が「ちょうど福岡の姉のところに行ってきたんです」と言います。次に何を言えますか？', '["「旅行はよくするんですか？」", "「お姉さんと仲がいいんですね。二人で何をしたんですか？」", "「福岡、いいですよね。熊本には行ったことがありますか？」", "「何日くらい行っていたんですか？」"]'::jsonb, '話を広げる前に、まず彼女の経験を受け止めて、理解を示しましょう。')
