  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('76af82d7-0b8b-4c02-ad43-4cff911e6e4f', 'ja', '全体として、より良い別れ方につながる考え方は、どれですか？', '["次につなげられる糸口に、耳を澄ませること", "良いタイミングを期待すること", "記憶に残ろうとすること", "気まずさを避けるために、手早く終えること"]'::jsonb, '糸口に結びつけると、また連絡を取る自然な理由が生まれます。')
