insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79854e99-6c36-4456-94b9-a4a09f901b6e', 'ja', '受け止めることは、なぜ心理的な安心感を生むのですか？', '["自分の経験が認められ、理解されたと感じられるから", "感情を読み取る力と、共感を示すから", "受け止められると、人は自分が重要で、大切にされていると感じるから"]'::jsonb, '理解されたと感じると、彼女はより自然に心を開きます。')
