insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7f4038e9-35fa-4928-b87c-513fe0b81ce9', 'ja', '彼女が、ストレスの多い一日だったと話したあと、避けるべきことは何ですか？', '["「ここに来ると、長い一日のあとでもいつも落ち着くんです」と言うこと", "「何がそんなにストレスだったんですか？」と尋ねること", "「ストレスにうまく対処できる方のように見えます」と伝えること"]'::jsonb, '自分と前向きな感情を結びつけてもらいましょう。彼女のストレスを問いただしてはいけません。')
