insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8105c1a4-951f-4041-9374-fb7c65a70dca', 'ja', '「弁護士をしています」というひと言は、どんな糸口をくれますか？', '["彼女の具体的な役割と責任", "扱っている法律の分野", "これまでの仕事の経験と、キャリアの歩み", "上のすべて"]'::jsonb, '糸口をたどるとは、彼女の話題をさらに掘り下げることです。彼女が口にしたことについて、具体的に尋ねましょう。')
